"""Individually reviewed baked apple preparations and two duplicate transcriptions."""
import pathlib,json,sqlite3,copy
root=pathlib.Path(__file__).parent
db=sqlite3.connect(root.parent.parent/'outputs/SavorShelf-Content-Repairs/grouped-work.sqlite3')
def original(id):return json.loads(db.execute('select record from recipes where id=?',(id,)).fetchone()[0])
records={r['sourceId']:r for r in json.loads((root/'content-overrides.json').read_text(encoding='utf-8'))}
aliases={r['id']:r for r in json.loads((root/'recipe-aliases.json').read_text(encoding='utf-8'))}
merges={'historical-7a33ef61c09f124fc63f8d75':'historical-410bed8021a75655d8648621','historical-d5a562346efda48b77b79ba1':'historical-01406f7933a04f2010ea02b9'}
newids=[]
def ing(k,a,u,n,s):return dict(key=k,amount=a,unit=u,name=n,substitution=s)
def apples(n):return ing('apples',n,'','medium firm baking apples, about 180 g each','Use another firm apple of similar size; sweetness and cooking time differ by variety. Avoid substituting very large apples without allowing longer cooking.')
def sugar(n,k='sugar'):return ing(k,n,'g','granulated sugar','Use the same weight of light brown sugar for a caramel-like flavor, or reduce to taste.')
def brown(n):return ing('brown',n,'g','light brown sugar','Use the same weight of granulated sugar for a lighter flavor.')
def butter(n):return ing('butter',n,'g','unsalted butter','Use the same weight of a block-style dairy-free butter alternative.')
def water(n):return ing('water',n,'ml','drinking water','Use the same volume of unsweetened apple juice for a sweeter pan sauce.')
def cinnamon(n):return ing('cinnamon',n,'g','ground cinnamon','Use half the weight of ground allspice for a different flavor, or omit.')
def raisins(n):return ing('raisins',n,'g','raisins','Use the same weight of sultanas or finely chopped dried apricots.')
def cream(n):return ing('cream',n,'ml','cold heavy whipping cream','Use the same volume of a plant-based cream specifically suitable for whipping; texture and flavor differ.')
def sour(n):return ing('sour',n,'g','cold sour cream','Use the same weight of plain full-fat yogurt for a tangier, lighter topping.')
def lemon(n):return ing('lemon',n,'ml','lemon juice','Use the same volume of orange juice for a sweeter citrus flavor.')
def zest(n):return ing('zest',n,'g','thin strips of lemon zest, yellow part only','Use the same weight of orange zest; avoid bitter white pith.')
STORAGE='Refrigerate leftovers within 2 hours at 4°C (40°F) or colder.'
def add(id,title,n,minutes,desc,items,steps,notes):
 s=original(id);r=copy.deepcopy(s['recipe']);r.update(title=title,description=desc,category='Desserts',servings=n,yieldUnit='servings',minutes=minutes,totalMinutes=minutes,ingredients=items,steps=steps,sourceStatus='adapted',versionNote='Modern measured adaptation',updatedAt='2026-09-22T15:00:00Z',notes=notes+' Missing amounts, oven settings, yields and timings are explicit modern estimates, not exact recovered historical measurements. Not kitchen-tested. Scaling changes ingredient quantities, not temperature or cooking time. '+STORAGE,source=s['recipe']['source']+' SavorShelf measured adaptation. General coring and oven technique reference: https://www.bbcgoodfoodme.com/recipes/baked-apples/')
 r.pop('variants',None);r['sourceAliases']=[old for old,new in merges.items() if new==id]
 for old in r['sourceAliases']:r['source']+=' Equivalent source retained: '+original(old)['recipe']['source']
 records[id]=dict(sourceId=id,bodySha256=s['bodySha256'],recipe=r);newids.append(id);return r
PREP='Rinse {{apples}}. Remove the cores and seeds with an apple corer, keeping the apples whole. Make a shallow cut through the skin around the middle of each apple to help limit splitting.'
BAKE='Bake for 30–45 minutes, checking after 25 minutes, until a small knife enters the flesh easily. Larger or firmer apples may take longer. Cover loosely with foil if the tops darken before the centers soften.'
add('historical-cd026bebc91036f4f73540dc','Pommes à la Portugaise (Sugar-Baked Apples)',4,60,'Whole cored apples bake with sugar in their centers and finish with a light dusting of powdered sugar.',[apples(4),sugar(50),ing('icing',10,'g','powdered sugar','Use 10 g fine granulated sugar for a slightly grainier finish.')],['Heat the oven to 180°C (356°F). '+PREP,'Stand the apples in a snug ovenproof dish lined with baking parchment. Divide {{sugar}} among their cavities and scatter any remainder around them. Cover loosely with foil.',BAKE+' Remove the foil for the final 10 minutes if the fruit is still pale.','Let stand for 5 minutes, then sprinkle with {{icing}} and serve warm.'],'The source title is retained as a historical recipe name, not an asserted Portuguese origin. An explicit four-apple batch replaces the unspecified dishful. Baking parchment and a loose cover replace the old silver-plate/camp-oven option.')
add('historical-d046b228d1330ca095782e7f','Gebraden Appelen (Raisin and Coconut Baked Apples)',8,60,'Peeled apples are filled with cinnamon sugar and raisins, dotted with butter and finished with a little toasted coconut.',[apples(8),sugar(100),cinnamon(4),butter(40),water(50),raisins(50),ing('coconut',10,'g','unsweetened desiccated coconut','Use 10 g finely chopped almonds if suitable, or omit.')],['Heat the oven to 180°C (356°F). Peel {{apples}} and remove the cores and seeds, keeping the apples whole. Arrange upright in a snug ovenproof dish.','Mix {{sugar}}, {{cinnamon}} and {{raisins}} and divide among the apple cavities. Dot the tops with {{butter}} and pour {{water}} into the bottom of the dish.','Bake for 30–45 minutes until a knife enters the flesh easily, spooning the pan liquid over the apples halfway through. Add a small splash of water if the pan dries.','Sprinkle {{coconut}} over the apples during the final 5 minutes, watching that it does not burn. Serve warm.'],'The source fruit count, sugar, butter, raisins and 50 ml water are retained. Cinnamon and coconut are assigned weights. The timing is extended when necessary for modern medium apples; tenderness takes precedence over the source 20–30 minutes.')
add('historical-43dc05f6e574053436366871','Baked Apples with Clove and Lemon Syrup',12,75,'Whole apples bake in a generously sweetened lemon syrup scented with whole cloves.',[apples(12),sugar(454),ing('cloves',6,'','whole cloves','Use 0.5 g ground cloves for a different texture; omit the spice-removal step for ground spice.'),zest(4),lemon(30),water(150)],['Heat the oven to 180°C (356°F). '+PREP,'Arrange the apples in a deep ovenproof dish in one layer. Scatter {{sugar}} around and into them. Add {{cloves}}, {{zest}}, {{lemon}} and {{water}} to the dish. Cover with foil.','Bake for 40–60 minutes until tender through, basting with the syrup after 25 minutes. Uncover for the final 10 minutes. Add a little water if the syrup begins to catch.','Remove and discard all whole cloves and lemon strips. Rest for 5 minutes and serve with the syrup spooned over the fruit.'],'The source one pound of sugar is retained as about 454 g. Twelve medium apples are supplied to define the previously unspecified fruit quantity. Water is added to start a syrup without scorching the sugar. Coring and an oven method complete the truncated source.')
r=add('historical-410bed8021a75655d8648621','Baked Apples with Raisins and Cloves',4,150,'Apples filled with raisins, brown sugar and cinnamon bake with cloves, then chill in their syrup for a soft fruit dessert.',[apples(4),brown(40),cinnamon(1),raisins(40),ing('cloves',4,'','whole cloves','Use 0.3 g ground cloves mixed into the filling; no removal is then needed.'),water(120),sugar(10)],['Heat the oven to 180°C (356°F). '+PREP,'Mix {{brown}}, {{cinnamon}} and {{raisins}} and divide among the cavities. Put {{cloves}} in the dish around the apples so they can be removed later. Add {{water}} and sprinkle the tops with {{sugar}}.',BAKE+' Spoon the pan liquid over the fruit halfway through; some splitting is consistent with this soft preparation.','Remove all whole cloves. Transfer the apples and syrup to a shallow container, cool briefly, then refrigerate within 2 hours. Chill for at least 1 hour before serving.'],'Two matching transcriptions are consolidated. The original cold serving style remains. Optional egg-white glaze is retained as a separate pasteurized-egg variation; total time includes an estimated chilling period.')
glaze=ing('white',30,'g','pasteurized liquid egg white suitable for whipping','Use a product labeled pasteurized; ordinary raw egg white is not an equivalent uncooked substitution.')
r['variants']=[dict(id='glazed',label='Pasteurized egg-white glaze and cream',ingredients=copy.deepcopy(r['ingredients'])+[glaze,ing('icing',60,'g','powdered sugar','Use finely ground caster sugar for a slightly grainier glaze.'),cream(120)],steps=copy.deepcopy(r['steps'])+['Whisk {{white}} with {{icing}} in a clean bowl until smooth and thick enough to coat a spoon. Spoon a thin layer over the chilled apples.','Whip {{cream}} until soft peaks form and serve alongside immediately. Keep the glazed fruit refrigerated until serving.'])]
r['source']+=' Pasteurized egg guidance: https://www.fda.gov/food/buy-store-serve-safe-food/what-you-need-know-about-egg-safety'
add('historical-3b505e140771aea40872b797','Jabłka Pieczone z Galaretą (Jelly-Filled Apple Halves)',4,45,'Unpeeled apple halves hold currant jelly and are served warm with sugar and cool sour cream.',[apples(2),ing('jelly',60,'g','redcurrant jelly','Use the same weight of another smooth fruit jelly; flavor and sweetness will change.'),sugar(10),sour(80)],['Heat the oven to 180°C (356°F). Rinse {{apples}}, halve lengthwise and scoop out every seed and the firm core, leaving a small hollow.','Put the halves cut-side up in a snug dish lined with baking parchment. Divide {{jelly}} among the hollows.','Bake for 25–35 minutes until the flesh is tender when pierced. Cover loosely if the jelly darkens too quickly.','Let cool for 5 minutes. Sprinkle with {{sugar}} and serve with {{sour}}.'],'The source pair of apples is retained as four half-apple portions. Serving sugar and sour cream, mentioned only in the method, are added to the measured ingredient list.')
add('historical-41592b34efb396b6df029897','Jabłka Pieczone ze Śliwkami (Prune-Filled Apples)',4,70,'Tart apples hold softened prunes and cinnamon sugar, with cold sour cream alongside.',[apples(4),ing('prunes',80,'g','pitted prunes','Use 80 g pitted dates for a sweeter filling; they may soften faster.'),water(160),sugar(16),cinnamon(1),sour(120)],['Put {{prunes}} and {{water}} in a small saucepan. Simmer gently for 8–10 minutes until the fruit is soft. Drain, retaining the cooking liquid, and chop the prunes.','Heat the oven to 180°C (356°F). '+PREP,'Fill the cavities with the softened prunes. Mix {{sugar}} with {{cinnamon}} and divide over the filling. Pour the reserved prune liquid into the dish.',BAKE+' Baste once and add a splash of water if the dish dries.','Rest for 5 minutes, then serve with {{sour}}.'],'The missing preparation of cooked prunes is supplied. Four grams of sugar per apple gives a modern measured teaspoon. The source slow baking and sour-cream finish remain.')
add('historical-0f3bc1baec5a674b583c79b0','Baked Apples in Sugar Syrup',6,65,'Unpeeled apples bake with sugar and water, producing a light syrup to spoon over the tender fruit.',[apples(6),sugar(75),water(240)],['Heat the oven to 180°C (356°F). '+PREP,'Set the apples upright in a snug ovenproof dish. Divide {{sugar}} over their cavities and pour {{water}} into the dish.','Bake for 40–50 minutes until very tender, basting twice with the liquid. Add water only if the dish is drying before the apples soften.','Let stand for 5 minutes, then spoon the syrup over the apples and serve.'],'Six source apples and the cup of water are retained; spoonfuls of sugar become 75 g total and the cup becomes 240 ml. Removing the cores is an explicit modern addition to the source blossom-end scooping.')
add('historical-2765374c6ef803d34acb60ff','Molasses-Baked Apples',4,60,'Whole apples bake beneath a dark molasses glaze for a deeply flavored, simple dessert.',[apples(4),ing('molasses',60,'g','mild unsulfured molasses','Use 60 g dark treacle for a stronger flavor or golden syrup for a lighter one; avoid bitter blackstrap as a direct substitute.'),water(40)],['Heat the oven to 180°C (356°F). '+PREP,'Place the apples in a snug ceramic or stainless-steel baking dish. Mix {{molasses}} with {{water}} and spoon over the apples. Cover loosely with foil.','Bake for 30 minutes. Uncover, baste and continue for 10–20 minutes until a knife enters the flesh easily. Watch the molasses closely and add a little water if it begins to catch.','Cool for 5 minutes and serve with the pan glaze.'],'A four-apple batch, molasses amount and oven instructions are supplied. A little water and a temporary cover are modern additions to reduce scorching; the source molasses character is retained.')
add('historical-b2e75165b5f4c6a062718e0a','Peeled Baked Apples with Lemon',6,155,'Peeled whole apples bake with lemon juice and zest, then chill in their light syrup for serving with cream.',[apples(6),sugar(90),lemon(15),zest(3),water(120),cream(120)],['Heat the oven to 180°C (356°F). Peel {{apples}} and core without cutting into pieces. Arrange upright in a snug baking dish.','Divide {{sugar}}, {{lemon}} and {{zest}} among the cavities. Pour {{water}} around the fruit.','Cover loosely with foil and bake for 40–60 minutes, basting once, until tender but still whole. Remove the foil for the final 10 minutes if needed.','Discard the lemon strips. Move the apples and syrup to a shallow container, cool briefly and refrigerate within 2 hours. Chill at least 1 hour. Serve with {{cream}} poured alongside.'],'The source dozen is halved to six apples. Missing sugar, lemon, water and cream quantities are supplied. Cream is selected from its cream-or-custard serving options. Chilling is included in the estimated total time; refrigeration replaces the unspecified cold-storage wording.')
add('historical-355ce4078f46f35dbfc915a9','Stekta Äpplen (Lightly Buttered Baked Apples)',6,60,'Cored apples bake in a buttered dish with a light sprinkle of sugar, keeping the fruit flavor prominent.',[apples(6),butter(15),sugar(30)],['Heat the oven to 180°C (356°F). '+PREP,'Use {{butter}} to coat the inside of a snug ovenproof dish. Stand the apples in it and sprinkle evenly with {{sugar}}. Cover loosely with foil.',BAKE+' Uncover for the last 10 minutes.','Rest for 5 minutes and serve warm, or cool briefly and refrigerate for serving cold.'],'A half batch retains the source gram weights in preference to its inconsistent tablespoon labels. The unpeeled option is selected. Whipped cream was optional in the source and is not required for this base preparation.')
add('historical-47594cfda891841509685ecc','Crumb-Coated Baked Apples with Vanilla Cream',6,150,'Peeled apples are coated in crisp rusk crumbs, filled with sugar and served chilled with vanilla-scented whipped cream.',[apples(6),ing('rusks',60,'g','plain rusks, finely crushed','Use 60 g fine dry breadcrumbs, or gluten-free crumbs if needed; sweetness and texture differ.'),sugar(150),butter(14),cream(200),ing('vanilla',8,'g','vanilla sugar','Use 8 g granulated sugar plus 1 ml vanilla extract.')],['Heat the oven to 180°C (356°F). Peel {{apples}} and carefully scoop out the cores and seeds, leaving a base in each apple to hold the filling.','Coat the damp peeled apples with {{rusks}}, pressing gently. Use {{butter|0.5}} to grease a snug ovenproof dish and stand the apples in it.','Divide {{sugar}} among the cavities, scattering any that does not fit around the fruit. Dot the tops with the remaining {{butter|0.5}}. Cover loosely with foil.','Bake for 35–50 minutes until tender, uncovering for the final 10 minutes to crisp the crumbs. Cover again if the crumbs darken too quickly.','Cool briefly, transfer to a shallow covered container and refrigerate within 2 hours. Chill for at least 1 hour.','Whip {{cream}} with {{vanilla}} until soft peaks form. Serve with the chilled apples.'],'The source twelve-apple recipe is halved. Rusk, sugar and butter spoon/cup amounts are assigned modern weights; the ambiguous cream notation becomes an explicit 200 ml for this batch. The crumb coating and cold whipped-cream presentation are retained.')
add('historical-01406f7933a04f2010ea02b9','Plain Baked Apples with Sugar',4,70,'Apples bake until very soft, then receive a simple sugar finish just before serving.',[apples(4),sugar(20)],['Heat the oven to 180°C (356°F). '+PREP,'Arrange the apples in a snug dish lined with baking parchment and cover loosely with foil. Bake for 45–60 minutes until very soft and beginning to split; uncover for the final 15 minutes.','Let stand for 5 minutes, then sprinkle with {{sugar}} and serve warm.'],'Two repeated Whitehouse transcriptions are consolidated. A four-apple yield and oven temperature are supplied. Coring and a loose initial cover are modern preparation additions; sugar is still added after baking rather than as a filling.')
r=add('historical-0cc9b9a2be2028e054f8868c','Baked Apples with Cinnamon and Cream',8,65,'Cored apples bake with cinnamon sugar and a little water, then are served with cream and the pan syrup.',[apples(8),sugar(100),cinnamon(.6),water(120),cream(160)],['Heat the oven to 200°C (392°F). '+PREP,'Mix {{sugar}} with {{cinnamon}} and fill the cavities. Bring {{water}} to a boil and pour it carefully into the bottom of the baking dish.','Bake for 30–45 minutes until soft, basting twice with the syrup. Cover loosely if the tops darken before the centers cook, and add water if the dish dries.','Rest for 5 minutes and serve with {{cream}} and the pan syrup.'],'The source eight-apple, half-cup sugar and quarter-teaspoon cinnamon formula is retained using modern weights. A separate nutmeg-and-lemon variation preserves its alternative flavoring.')
items=[i for i in copy.deepcopy(r['ingredients']) if i['key']!='cinnamon']+[ing('nutmeg',.5,'g','ground nutmeg','Omit or return to the cinnamon base recipe.'),lemon(5),ing('zest',1,'g','finely grated lemon zest','Use the same weight of orange zest, or omit.')]
steps=copy.deepcopy(r['steps']);steps[1]='Mix {{sugar}} with {{nutmeg}} and {{zest}} and fill the cavities. Drizzle {{lemon}} into them. Bring {{water}} to a boil and pour it carefully into the bottom of the baking dish.'
r['variants']=[dict(id='nutmeg-lemon',label='Nutmeg and lemon',ingredients=items,steps=steps)]
assert len(newids)==13
for old,new in merges.items():aliases[old]=dict(id=old,canonicalId=new,bodySha256=original(old)['bodySha256'],reason='Full ingredients and cooking method are equivalent transcriptions from the same book. Both source credits are retained, with any optional glaze preserved in the canonical recipe.')
(root/'content-overrides.json').write_text(json.dumps(list(records.values()),ensure_ascii=False,indent=2),encoding='utf-8')
(root/'recipe-aliases.json').write_text(json.dumps(list(aliases.values()),ensure_ascii=False,indent=2),encoding='utf-8')
for id in newids:db.execute('insert or replace into decisions values(?,?,?,?,?)',(id,records[id]['bodySha256'],'prepared-adaptation','Full baked-apple preparation reviewed; measured modern quantities, oven endpoint and variations','repair-batch-007.py'))
for old in merges:db.execute('insert or replace into decisions values(?,?,?,?,?)',(old,aliases[old]['bodySha256'],'prepared-merge',aliases[old]['reason'],'repair-batch-007.py'))
db.commit()
print(json.dumps(dict(newAdaptations=len(newids),newMergedSources=len(merges),totalOverrides=len(records),totalAliases=len(aliases))))
